from itertools import product
def fitpoly(d):
    cols=[eps**i*T**j for i,j in product(range(d+1),range(d+1)) if i+j<=d]
    X=np.array(cols).T
    c,res,_,_=np.linalg.lstsq(X,sigma,rcond=None)
    r=sigma-X@c
    return np.mean(r**2)/np.var(sigma)
